import { env } from "cloudflare:workers";
type PlatformEnv={DB:D1Database;UPLOADS?:R2Bucket;SUPABASE_URL?:string;SUPABASE_PUBLISHABLE_KEY?:string;SUPABASE_SERVICE_ROLE_KEY?:string;DISCORD_CLIENT_ID?:string;DISCORD_CLIENT_SECRET?:string;DISCORD_PUBLIC_KEY?:string;DISCORD_BOT_TOKEN?:string;DISCORD_APPLICATION_ID?:string;DISCORD_GUILD_ID?:string;GOOGLE_CLIENT_ID?:string;GOOGLE_CLIENT_SECRET?:string;BOT_INTERNAL_KEY?:string;STEAM_API_KEY?:string;TELEMETRY_API_KEY?:string;FOUNDER_EMAIL?:string};
export const platformEnv=()=>env as unknown as PlatformEnv;
export function publicRequestOrigin(request:Request){const url=new URL(request.url),forwardedHost=request.headers.get("x-forwarded-host")?.split(",")[0]?.trim(),host=forwardedHost||request.headers.get("host")||url.host,normalized=host.toLowerCase();if(normalized.startsWith("localhost")||normalized.startsWith("127.0.0.1")){const forwardedProto=request.headers.get("x-forwarded-proto")?.split(",")[0]?.trim(),protocol=forwardedProto||url.protocol.replace(":","");return`${protocol}://${host}`}return"https://vtc-truck-hub.de"}
export const isSecureRequest=(request:Request)=>publicRequestOrigin(request).startsWith("https://");
