async function seed(db:D1Database){await db.prepare(`INSERT OR IGNORE INTO vtcs (id,slug,name,tag,description,country,city,games,languages,timezone,truckersmp_id,discord_url,website_url,verified,driver_count,total_km) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind("vtc-ngl","nordlicht-logistik","Nordlicht Logistik","NGL","Deutschsprachige Community für realistische Touren, faire Disposition und gemeinsame Konvois.","Deutschland","Hamburg","ETS2,ATS","Deutsch,Englisch","Europe/Berlin","48291","https://discord.gg/example","https://example.com",1,148,12400000).run();await db.prepare(`INSERT OR IGNORE INTO vtcs (id,slug,name,tag,description,country,city,games,languages,timezone,verified,driver_count,total_km) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind("vtc-ast","asphalt-titans","Asphalt Titans","AST","Aktive ETS2-Spedition mit Fokus auf Events.","Österreich","Wien","ETS2","Deutsch","Europe/Vienna",1,86,8900000).run();await db.prepare(`INSERT OR IGNORE INTO vtcs (id,slug,name,tag,description,country,city,games,languages,timezone,verified,driver_count,total_km) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind("vtc-r66","route-66-hauling","Route 66 Hauling","R66","American Truck Simulator von Küste zu Küste.","USA","Phoenix","ATS","English","America/Phoenix",0,64,6100000).run();await db.prepare(`INSERT OR IGNORE INTO economy_settings (id,vtc_id,name) VALUES ('economy-global',NULL,'Plattformstandard')`).run();await db.prepare(`INSERT OR IGNORE INTO vtc_profiles (vtc_id,founded_at,motto,main_language,contact_name,requirements,rules,probation_info,partner_seeking,beginner_friendly,driving_modes) VALUES ('vtc-ngl','2021-04-12','Nicht die schnellste Route zählt, sondern wer sie mit dir fährt.','Deutsch','Geschäftsführung','["Mindestalter 16 Jahre","Respektvolle Fahrweise","Discord erforderlich"]','["Respektvoller Umgang","Keine absichtlichen Kollisionen","Aufträge ehrlich erfassen"]','Vier Wochen Probezeit mit persönlichem Ansprechpartner',1,1,'["realistic","convoy","career"]')`).run();await db.prepare(`INSERT OR IGNORE INTO application_forms (vtc_id,fields,cooldown_days,probation_days,auto_role_id,open) VALUES ('vtc-ngl','[{"id":"discordId","label":"Discord-ID","type":"text","required":true},{"id":"truckersmpId","label":"TruckersMP-ID","type":"text","required":true},{"id":"hours","label":"Spielstunden","type":"number","required":true},{"id":"experience","label":"Fahrerfahrung","type":"textarea","required":true},{"id":"previousVtcs","label":"Frühere Speditionen","type":"textarea","required":false},{"id":"motivation","label":"Warum möchtest du beitreten?","type":"textarea","required":true},{"id":"availability","label":"Verfügbarkeit","type":"text","required":true}]',30,28,'role-ngl-probation',1)`).run();for(const [key,name,rank,permissions] of standardRoles)await db.prepare(`INSERT OR IGNORE INTO roles (id,vtc_id,name,color,rank,permissions,protected) VALUES (?, 'vtc-ngl', ?, ?, ?, ?, ?)`).bind(`role-ngl-${key}`,name,key==="owner"?"#22d3c5":"#6f8793",rank,JSON.stringify(permissions),key==="owner"?1:0).run();for(const [id,name,color] of [["department-ngl-management","Geschäftsführung","#22d3c5"],["department-ngl-hr","Personalabteilung","#7c8cff"],["department-ngl-dispatch","Disposition","#f3a84f"],["department-ngl-drivers","Fahrbetrieb","#4fcf86"]])await db.prepare(`INSERT OR IGNORE INTO departments (id,vtc_id,name,color) VALUES (?,'vtc-ngl',?,?)`).bind(id,name,color).run();const env=platformEnv(),founder=env.FOUNDER_EMAIL?.trim().toLowerCase();if(founder){await db.prepare(`INSERT INTO platform_settings (key,value) VALUES ('founder_email',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value`).bind(founder).run();const user=await db.prepare(`SELECT id FROM users WHERE lower(email)=?`).bind(founder).first<{id:string}>();if(user){await db.prepare(`INSERT OR IGNORE INTO memberships (id,vtc_id,user_id,role_id,driver_number,status,department) VALUES (?,'vtc-ngl',?,'role-ngl-owner','NGL-001','active','Geschäftsführung')`).bind(`membership-ngl-${user.id}`,user.id).run();await db.prepare(`INSERT OR IGNORE INTO personnel_records (id,vtc_id,user_id,status,language,timezone,main_game) VALUES (?,'vtc-ngl',?,'active','Deutsch','Europe/Berlin','ETS2,ATS')`).bind(`personnel-ngl-${user.id}`,user.id).run()}}const guildId=env.DISCORD_GUILD_ID?.trim();if(guildId)await db.prepare(`INSERT OR IGNORE INTO discord_guilds (guild_id,vtc_id,enabled) VALUES (?,'vtc-ngl',1)`).bind(guildId).run()}
const enc=new TextEncoder();const hex=(b:Uint8Array)=>Array.from(b).map(x=>x.toString(16).padStart(2,"0")).join("");export const randomId=()=>crypto.randomUUID();
export async function hashPassword(password:string,salt=hex(crypto.getRandomValues(new Uint8Array(16)))){const key=await crypto.subtle.importKey("raw",enc.encode(password),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:enc.encode(salt),iterations:120000},key,256);return`pbkdf2$120000$${salt}$${hex(new Uint8Array(bits))}`}
export async function verifyPassword(password:string,stored:string){const[,iterations,salt,expected]=stored.split("$");const key=await crypto.subtle.importKey("raw",enc.encode(password),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:enc.encode(salt),iterations:Number(iterations)},key,256);return hex(new Uint8Array(bits))===expected}
export async function createSession(userId:string,request:Request){await ensureDatabase();const token=randomId()+randomId(),expires=new Date(Date.now()+30*864e5).toISOString();await platformEnv().DB.prepare(`INSERT INTO sessions (id,user_id,expires_at,user_agent) VALUES (?,?,?,?)`).bind(token,userId,expires,request.headers.get("user-agent")?.slice(0,255)??null).run();return`convoy_session=${token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=2592000${isSecureRequest(request)?"; Secure":""}`}
export async function getSessionUser(request:Request){await ensureDatabase();const token=request.headers.get("cookie")?.match(/(?:^|; )convoy_session=([^;]+)/)?.[1];if(!token)return null;return platformEnv().DB.prepare(`SELECT users.id,users.email,users.display_name AS displayName FROM sessions JOIN users ON users.id=sessions.user_id WHERE sessions.id=? AND sessions.expires_at>CURRENT_TIMESTAMP`).bind(token).first<{id:string,email:string|null,displayName:string}>()}
export async function requireFounder(request:Request){const user=await getSessionUser(request);if(!user?.email)return null;const founder=await platformEnv().DB.prepare(`SELECT value FROM platform_settings WHERE key='founder_email'`).first<{value:string}>();return founder?.value.toLowerCase()===user.email.toLowerCase()?user:null}
export async function requireVtcPermission(request:Request,vtcId:string,permission:string){const user=await getSessionUser(request);if(!user)return null;const founder=await platformEnv().DB.prepare(`SELECT value FROM platform_settings WHERE key='founder_email'`).first<{value:string}>();if(founder?.value.toLowerCase()===user.email?.toLowerCase())return {...user,permissions:["*"]};const row=await platformEnv().DB.prepare(`SELECT r.permissions FROM memberships m JOIN roles r ON r.id=m.role_id WHERE m.vtc_id=? AND m.user_id=? AND m.status='active'`).bind(vtcId,user.id).first<{permissions:string}>();const permissions=row?JSON.parse(row.permissions) as string[]:[];const delegated=await platformEnv().DB.prepare(`SELECT permissions FROM role_delegations WHERE vtc_id=? AND to_user_id=? AND active=1 AND starts_at<=CURRENT_TIMESTAMP AND ends_at>CURRENT_TIMESTAMP`).bind(vtcId,user.id).all<{permissions:string}>();for(const item of delegated.results)permissions.push(...JSON.parse(item.permissions));return permissions.includes("*")||permissions.includes(permission)?{...user,permissions:[...new Set(permissions)]}:null}
export async function resolveVtcId(request:Request,requested?:string|null){const user=await getSessionUser(request);if(!user)return null;const realRequested=requested&&!['vtc-ngl','vtc-ast','vtc-r66'].includes(requested)?requested:null;if(realRequested){const own=await platformEnv().DB.prepare(`SELECT vtc_id AS vtcId FROM memberships WHERE user_id=? AND vtc_id=? AND status='active'`).bind(user.id,realRequested).first<{vtcId:string}>();return own?.vtcId??null}const row=await platformEnv().DB.prepare(`SELECT vtc_id AS vtcId FROM memberships WHERE user_id=? AND status='active' ORDER BY joined_at LIMIT 1`).bind(user.id).first<{vtcId:string}>();return row?.vtcId??null}
export const apiError=(message:string,status=400)=>Response.json({error:message},{status});export async function audit(action:string,entityType:string,entityId:string|null,actorId:string|null,detail:unknown={},vtcId:string|null=null){await platformEnv().DB.prepare(`INSERT INTO audit_logs (vtc_id,actor_id,action,entity_type,entity_id,detail) VALUES (?,?,?,?,?,?)`).bind(vtcId,actorId,action,entityType,entityId,JSON.stringify(detail)).run()}
export async function sha256(value:string){return hex(new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode(value))))}
const base32Alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
export function randomBase32(length=32){let out="";const bytes=crypto.getRandomValues(new Uint8Array(length));for(const b of bytes)out+=base32Alphabet[b%32];return out}
function decodeBase32(value:string){let bits="";for(const c of value.replace(/=+$/,"").toUpperCase()){const n=base32Alphabet.indexOf(c);if(n>=0)bits+=n.toString(2).padStart(5,"0")}const out=[];for(let i=0;i+8<=bits.length;i+=8)out.push(parseInt(bits.slice(i,i+8),2));return new Uint8Array(out)}
export async function verifyTotp(secret:string,code:string){if(!/^\d{6}$/.test(code))return false;const key=await crypto.subtle.importKey("raw",decodeBase32(secret),{name:"HMAC",hash:"SHA-1"},false,["sign"]);const step=Math.floor(Date.now()/30000);for(let drift=-1;drift<=1;drift++){let n=step+drift;const msg=new Uint8Array(8);for(let i=7;i>=0;i--){msg[i]=n&255;n=Math.floor(n/256)}const h=new Uint8Array(await crypto.subtle.sign("HMAC",key,msg)),o=h[h.length-1]&15,num=((h[o]&127)<<24|(h[o+1]&255)<<16|(h[o+2]&255)<<8|(h[o+3]&255))%1000000;if(String(num).padStart(6,"0")===code)return true}return false}
